param(
    [ValidateSet("Install","Restore")]
    [string]$Mode = "Install",
    [string]$GamePath = ""
)

$ErrorActionPreference = "Stop"
$Version = "V1.0.0"
$AppId = "646200"
$GameName = "Dead Effect 2 VR"
$ExpectedOriginalSha256 = "AD2019B343D3F216134C85EAC680EC5666CC4F53DF4A0E14E5100BE441B7C03D"
$ExpectedV006Sha256 = "8858F9640F7CCC4E2454824E387246B9F28AE64622883B963DCC5AD260788A4E"
$ExpectedV007Sha256 = "E0C2F1FF0ABB096AC0A444B63CCF5C89775CE7D79D83F2898B15AC5C524941CD"
$ExpectedV0081Sha256 = "388EBEA7C5E64F6FEA3C2ABC17E8A5C8F29AC825CC8F6ACA80D50495594F2A54"
$ScriptDir = Split-Path -Parent $MyInvocation.MyCommand.Path
$BaseReportDir = if ($env:LOCALAPPDATA) { Join-Path $env:LOCALAPPDATA "LoVeMaKeRz\DeadEffect2VR_FR" } else { Join-Path $env:TEMP "DeadEffect2VR_FR" }
$ReportDir = Join-Path $BaseReportDir "Reports"
New-Item -ItemType Directory -Force -Path $ReportDir | Out-Null
$LogPath = Join-Path $ReportDir "PATCH.log"

function Write-Log([string]$Text) {
    $stamp = Get-Date -Format "yyyy-MM-dd HH:mm:ss"
    $line = "$stamp [INFO] $Text"
    Add-Content -LiteralPath $LogPath -Value $line -Encoding UTF8
    Write-Host $line
}

function Convert-VdfPath([string]$PathText) {
    if ([string]::IsNullOrWhiteSpace($PathText)) { return $null }
    return ($PathText -replace '\\\\','\')
}

function Get-SteamRoots {
    $roots = New-Object System.Collections.Generic.List[string]
    $regCandidates = @(
        'HKCU:\Software\Valve\Steam',
        'HKLM:\SOFTWARE\WOW6432Node\Valve\Steam',
        'HKLM:\SOFTWARE\Valve\Steam'
    )
    foreach ($r in $regCandidates) {
        try {
            $p = Get-ItemProperty -Path $r -ErrorAction Stop
            foreach ($name in @('SteamPath','InstallPath')) {
                if ($p.$name -and (Test-Path -LiteralPath $p.$name)) {
                    $roots.Add([IO.Path]::GetFullPath($p.$name))
                }
            }
        } catch {}
    }
    foreach ($p in @("${env:ProgramFiles(x86)}\Steam", "$env:ProgramFiles\Steam", 'C:\Steam')) {
        if ($p -and (Test-Path -LiteralPath $p)) { $roots.Add([IO.Path]::GetFullPath($p)) }
    }
    return $roots | Select-Object -Unique
}

function Get-SteamLibraries {
    $libs = New-Object System.Collections.Generic.List[string]
    foreach ($steamRoot in (Get-SteamRoots)) {
        $libs.Add($steamRoot)
        $vdf = Join-Path $steamRoot 'steamapps\libraryfolders.vdf'
        if (Test-Path -LiteralPath $vdf) {
            try {
                $raw = Get-Content -LiteralPath $vdf -Raw -ErrorAction Stop
                foreach ($m in [regex]::Matches($raw, '"path"\s+"([^"]+)"', 'IgnoreCase')) {
                    $p = Convert-VdfPath $m.Groups[1].Value
                    if ($p -and (Test-Path -LiteralPath $p)) { $libs.Add([IO.Path]::GetFullPath($p)) }
                }
            } catch {}
        }
    }
    foreach ($d in (Get-PSDrive -PSProvider FileSystem -ErrorAction SilentlyContinue)) {
        if (-not $d.Root) { continue }
        foreach ($candidate in @((Join-Path $d.Root 'SteamLibrary'), (Join-Path $d.Root 'Steam'))) {
            if (Test-Path -LiteralPath (Join-Path $candidate 'steamapps')) {
                $libs.Add([IO.Path]::GetFullPath($candidate))
            }
        }
    }
    return $libs | Select-Object -Unique
}

function Test-GameFolder([string]$Path) {
    if ([string]::IsNullOrWhiteSpace($Path)) { return $false }
    return (
        (Test-Path -LiteralPath (Join-Path $Path 'DeadEffect2_Data\resources.assets')) -and
        (Test-Path -LiteralPath (Join-Path $Path 'DeadEffect2_Data\Managed\Assembly-CSharp.dll'))
    )
}

function Find-GamePath {
    foreach ($lib in (Get-SteamLibraries)) {
        $manifest = Join-Path $lib "steamapps\appmanifest_$AppId.acf"
        if (Test-Path -LiteralPath $manifest) {
            try {
                $raw = Get-Content -LiteralPath $manifest -Raw
                $installDir = $GameName
                $m = [regex]::Match($raw, '"installdir"\s+"([^"]+)"', 'IgnoreCase')
                if ($m.Success) { $installDir = $m.Groups[1].Value }
                $p = Join-Path $lib ("steamapps\common\{0}" -f $installDir)
                if (Test-GameFolder $p) { return [IO.Path]::GetFullPath($p) }
            } catch {}
        }
        $direct = Join-Path $lib ("steamapps\common\{0}" -f $GameName)
        if (Test-GameFolder $direct) { return [IO.Path]::GetFullPath($direct) }
    }
    return $null
}

function Select-GameFolder {
    try {
        Add-Type -AssemblyName System.Windows.Forms
        $dlg = New-Object System.Windows.Forms.FolderBrowserDialog
        $dlg.Description = 'Select the Steam folder for Dead Effect 2 VR.'
        $dlg.ShowNewFolderButton = $false
        if ($dlg.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) {
            if (Test-GameFolder $dlg.SelectedPath) { return [IO.Path]::GetFullPath($dlg.SelectedPath) }
        }
    } catch {}
    return $null
}

function Get-Sha256([string]$Path) {
    return (Get-FileHash -Algorithm SHA256 -LiteralPath $Path).Hash.ToUpperInvariant()
}

$cs = @"
using System;
using System.IO;
using System.Text;
using System.Linq;
using System.Collections.Generic;

public sealed class DE2ObjectInfo {
    public long PathID;
    public long Offset;
    public uint Size;
    public int TypeID;
    public int ClassID;
    public long ByteStartMetaPos;
    public long ByteSizeMetaPos;
}

public sealed class DE2SerializedFile : IDisposable {
    private FileStream fs;
    private BinaryReader br;
    private bool little;
    public uint Version { get; private set; }
    public long DataOffset { get; private set; }
    public long FileLength { get { return fs.Length; } }
    public List<DE2ObjectInfo> Objects { get; private set; }

    public DE2SerializedFile(string path) {
        fs = new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.Read);
        br = new BinaryReader(fs);
        Objects = new List<DE2ObjectInfo>();
        Parse();
    }

    private static uint U32BE(BinaryReader r) {
        byte[] b = r.ReadBytes(4);
        if (b.Length != 4) throw new EndOfStreamException();
        return ((uint)b[0] << 24) | ((uint)b[1] << 16) | ((uint)b[2] << 8) | b[3];
    }

    private int I32() {
        byte[] b = br.ReadBytes(4);
        if (b.Length != 4) throw new EndOfStreamException();
        if (!little) Array.Reverse(b);
        return BitConverter.ToInt32(b,0);
    }

    private uint U32() {
        byte[] b = br.ReadBytes(4);
        if (b.Length != 4) throw new EndOfStreamException();
        if (!little) Array.Reverse(b);
        return BitConverter.ToUInt32(b,0);
    }

    private short I16() {
        byte[] b = br.ReadBytes(2);
        if (b.Length != 2) throw new EndOfStreamException();
        if (!little) Array.Reverse(b);
        return BitConverter.ToInt16(b,0);
    }

    private ushort U16() {
        byte[] b = br.ReadBytes(2);
        if (b.Length != 2) throw new EndOfStreamException();
        if (!little) Array.Reverse(b);
        return BitConverter.ToUInt16(b,0);
    }

    private long I64() {
        byte[] b = br.ReadBytes(8);
        if (b.Length != 8) throw new EndOfStreamException();
        if (!little) Array.Reverse(b);
        return BitConverter.ToInt64(b,0);
    }

    private string CString() {
        List<byte> bytes = new List<byte>();
        while (true) {
            int v = fs.ReadByte();
            if (v < 0) throw new EndOfStreamException();
            if (v == 0) break;
            bytes.Add((byte)v);
        }
        return Encoding.UTF8.GetString(bytes.ToArray());
    }

    private void Align4() {
        long p = fs.Position;
        long a = (p + 3L) & ~3L;
        if (a != p) fs.Position = a;
    }

    private void Parse() {
        fs.Position = 0;
        uint metadataSize = U32BE(br);
        uint fileSize = U32BE(br);
        Version = U32BE(br);
        uint dataOffset32 = U32BE(br);
        DataOffset = dataOffset32;
        if (Version < 9 || Version > 21) throw new InvalidDataException("Unsupported Unity serialized version: " + Version);
        byte endian = br.ReadByte();
        br.ReadBytes(3);
        little = endian == 0;
        CString();
        I32();
        bool enableTypeTree = br.ReadByte() != 0;
        int typeCount = I32();
        List<int> typeClassIDs = new List<int>();
        for (int i=0; i<typeCount; i++) {
            int classID = I32();
            typeClassIDs.Add(classID);
            if (Version >= 16) br.ReadByte();
            if (Version >= 17) I16();
            if (Version >= 13) {
                if (Version < 16 && classID < 0) br.ReadBytes(16);
                else if (Version >= 16 && classID == 114) br.ReadBytes(16);
                br.ReadBytes(16);
            }
            if (enableTypeTree) throw new InvalidDataException("TypeTree-enabled serialized files are not supported.");
        }
        if (Version >= 7 && Version < 14) I32();
        int objectCount = I32();
        if (objectCount < 0 || objectCount > 5000000) throw new InvalidDataException("Invalid object count: " + objectCount);
        for (int i=0; i<objectCount; i++) {
            if (Version >= 14) Align4();
            long pathID = Version < 14 ? I32() : I64();
            long byteStartPos = fs.Position;
            long byteStart = Version >= 22 ? I64() : U32();
            long byteSizePos = fs.Position;
            uint byteSize = U32();
            int typeID = I32();
            int classID;
            if (Version < 16) classID = U16();
            else classID = (typeID >= 0 && typeID < typeClassIDs.Count) ? typeClassIDs[typeID] : -9999;
            if (Version < 11) U16();
            if (Version >= 11 && Version < 17) I16();
            if (Version == 15 || Version == 16) br.ReadByte();
            Objects.Add(new DE2ObjectInfo {
                PathID=pathID,
                Offset=DataOffset + byteStart,
                Size=byteSize,
                TypeID=typeID,
                ClassID=classID,
                ByteStartMetaPos=byteStartPos,
                ByteSizeMetaPos=byteSizePos
            });
        }
    }

    public byte[] ReadObject(long pathID) {
        DE2ObjectInfo o = Objects.Find(x => x.PathID == pathID);
        if (o == null) throw new InvalidDataException("PathID not found: " + pathID);
        fs.Position = o.Offset;
        byte[] b = br.ReadBytes((int)o.Size);
        if (b.Length != (int)o.Size) throw new EndOfStreamException();
        return b;
    }

    public bool IsLittleEndian { get { return little; } }

    public void Dispose() {
        if (br != null) br.Close();
        if (fs != null) fs.Close();
    }
}

