                { "Story_Chapter", "Chapitre {0} :" },
                { "Tutorial_LookTouch", "Touchez l\u2019\u00E9cran et faites glisser votre doigt" },
                { "Tutorial_LookGamepad", "Utilisez le stick analogique droit" },
                { "Tutorial_LookMouse", "Utilisez la souris" },
