                { "VrHoldType_Hold", "Maintenir" },
                { "VrHoldType_Click", "Cliquer" },
                { "VrHoldType_DoubleClick", "Double-cliquer" },
                { "VrHoldType_HoldOrClickDesc", "Maintenez ou cliquez sur Grip pour prendre l\u2019arme dans son \u00E9tui. Elle reste en main jusqu\u2019\u00E0 ce que vous la rangiez." },
                { "VrHoldType_HoldDesc", "Maintenez Grip pour prendre l\u2019arme dans son \u00E9tui. Elle revient dans l\u2019\u00E9tui d\u00E8s que vous rel\u00E2chez Grip." },
                { "VrHoldType_ClickDesc", "Cliquez sur Grip pour prendre l\u2019arme dans son \u00E9tui. Elle reste en main jusqu\u2019\u00E0 ce que vous la rangiez." },
                { "VrHoldType_DoubleClickDesc", "Double-cliquez sur Grip pour prendre l\u2019arme dans son \u00E9tui. Elle reste en main jusqu\u2019\u00E0 ce que vous la rangiez." },
                { "VrHoldType_HoldDescEx", "Maintenez Grip pour prendre l\u2019objet \u00E0 lancer dans son \u00E9tui. D\u00E8s que vous rel\u00E2chez Grip, il est lanc\u00E9 ou replac\u00E9 dans l\u2019\u00E9tui." },
                { "VrHoldType_DoubleClickDescEx", "Double-cliquez puis maintenez Grip pour prendre l\u2019objet \u00E0 lancer dans son \u00E9tui. D\u00E8s que vous rel\u00E2chez Grip, il est lanc\u00E9 ou replac\u00E9 dans l\u2019\u00E9tui." },
                { "VrWeaponSettings", "R\u00E9glages de l\u2019arme" },
