                { "QuestItem_Supplies", "Pack de ravitaillement" },
                { "QuestItemDesc_Supplies", "Tas de provisions diverses." },
                { "QuestItem_BoltsNuts", "Pi\u00E8ces d\u00E9tach\u00E9es" },
                { "QuestItemDesc_BoltsNuts", "Tas de pi\u00E8ces d\u00E9tach\u00E9es." },
                { "QuestItem_Sample", "\u00C9chantillon" },
