                { "LevelName_BaseDefense_01", "Base avanc\u00E9e" },
                { "LevelDateTime_BaseDefense_01", "Lieu : ESS Meridian, positions d\u00E9fensives avanc\u00E9es" },
                { "LevelName_BaseDefense_02", "Contr\u00F4le de vol Epsilon" },
                { "LevelDateTime_BaseDefense_02", "Lieu : ESS Meridian, contr\u00F4le de vol Epsilon" },
                { "LevelName_Train01_survive", "Gare" },
                { "LevelDateTime_Train01_survive", "Lieu : ESS Meridian, station de jet lift abandonn\u00E9e" },
                { "LevelName_Generic18", "Traitement de l\u2019air" },
                { "LevelDateTime_Generic18", "Lieu : ESS Meridian, installation de traitement de l\u2019air" },
                { "LevelName_Generic19", "Recherche m\u00E9dicale" },
                { "LevelDateTime_Generic19", "Lieu : ESS Meridian, installation de recherche m\u00E9dicale 12" },
                { "LevelName_LoneWolf_02", "Maintenance propulsion Gamma" },
                { "LevelDateTime_LoneWolf_02", "Lieu : ESS Meridian, maintenance propulsion Gamma" },
                { "LevelObjective_LoneWolf", "Traquer les soldats" },
                { "LevelDescription_LoneWolf", "La Force Delta tente d\u2019\u00E9tablir une base ici. Persuadez-les d\u2019aller voir ailleurs." },
                { "MissionLoadedText1_HUB_Central_00", "Interm\u00E8de : fondation de la base" },
                { "MissionLoadedText2_HUB_Central_00", "Lieu : base secr\u00E8te" },
                { "MissionLoadedText3_HUB_Central_00", "Cet endroit devrait \u00EAtre s\u00FBr un moment. Il est temps d\u2019obtenir quelques r\u00E9ponses." },
                { "MissionLoadedText1_HUB_Central_01", "Interm\u00E8de : base de la R\u00E9sistance" },
                { "MissionLoadedText2_HUB_Central_01", "Lieu : base secr\u00E8te" },
                { "MissionLoadedText3_HUB_Central_01", "Un peu de repos. Et peut-\u00EAtre de nouvelles armes et du mat\u00E9riel." },
                { "MissionLoadedText1_HUB_Central_02", "Interm\u00E8de : pause" },
                { "MissionLoadedText2_HUB_Central_02", "Lieu : r\u00E9serve d\u2019\u00E9quipement temporaire" },
                { "MissionLoadedText3_HUB_Central_02", "Refaites le plein de munitions et continuez." },
                { "MissionLoadedText1_VirtualR_HUB", "Interm\u00E8de : pause" },
                { "MissionLoadedText2_VirtualR_HUB", "Lieu : r\u00E9serve d\u2019\u00E9quipement temporaire" },
                { "MissionLoadedText3_VirtualR_HUB", "V\u00E9rifiez votre \u00E9quipement et continuez." },
                { "MissionLoadedText1", "Mission secr\u00E8te" },
                { "MissionLoadedText2", "Date : classifi\u00E9e\\nLieu : classifi\u00E9" },
                { "MissionLoadedText3", "Niveau de classification : vous n\u2019avez pas l\u2019habilitation n\u00E9cessaire." },
                { "DeathQuote_1", "M\u00EAme le g\u00E2teau a disparu." },
                { "DeathQuote_2", "Combo cass\u00E9 !" },
                { "DeathQuote_3", "Portez-moi, moi qui suis tomb\u00E9 au combat, par-del\u00E0 l\u2019espace et les mers\u2026" },
                { "DeathQuote_4", "Soyez t\u00E9moins !" },
                { "DeathQuote_5", "Le Valhalla m\u2019attend !" },
                { "DeathQuote_6", "N\u2019envoyez jamais un clone faire le travail d\u2019un guerrier." },
                { "DeathQuote_7", "R\u00E9animez-moi !" },
                { "DeathQuote_8", "Attendez, ce n\u2019est pas comme \u00E7a que \u00E7a s\u2019est pass\u00E9 !" },
                { "DeathQuote_9", "Silence ! Je vous tue !" },
                { "DeathQuote_10", "Installez-vous confortablement, soldat. Restez un moment." },
                { "DeathQuote_11", "Oui, ici on peut mourir gratuitement." },
                { "DeathQuote_12", "Une nouvelle vie ne co\u00FBte que quelques cr\u00E9dits." },
                { "DeathQuote_13", "La mort est plus l\u00E9g\u00E8re qu\u2019une plume. La r\u00E9animation co\u00FBte beaucoup plus cher." },
                { "DeathQuote_14", "N\u2019abandonnez jamais, ne vous rendez jamais !" },
                { "DeathQuote_15", "Votre objectif n\u2019est pas de mourir. Votre objectif est de tuer !" },
                { "DeathQuote_16", "Choisissez votre mort : rapide et indolore, ou lente et atroce ?" },
                { "DeathQuote_17", "Vous venez de mourir. Merci de prendre votre re\u00E7u." },
                { "DeathQuote_18", "Mourir ou payer pour \u00EAtre r\u00E9anim\u00E9. Telle est la question." },
                { "DeathQuote_19", "Bon. C\u2019est fini pour moi." },
                { "DeathQuote_20", "C\u2019\u00E9tait un beau jour pour mourir." },
                { "LevelName_Generic20", "Terraformation Gamma" },
                { "LevelDateTime_Generic20", "Lieu : ESS Meridian, terraformation Gamma" },
                { "LevelName_Generic21", "Passerelle de commandement" },
                { "LevelDateTime_Generic21", "Lieu : ESS Meridian, passerelle de commandement" },
                { "LevelNameGeneric_G_Gardens_03", "Zone de recherche Delta Labs" },
                { "LevelNameGeneric_Hangar03", "Observatoire astronomique avanc\u00E9" },
                { "LevelNameGeneric_TrainYard01", "Station de recyclage de l\u2019eau" },
                { "LevelNameGeneric_Hangar02", "Hangar de ravitaillement et entrep\u00F4ts" },
                { "LevelNameGeneric_Generic05", "Entrep\u00F4t 7" },
                { "LevelLoadedText_DeathMatch1", "Ne perdez pas de temps \u00E0 les trier, tuez-les tous !" },
                { "LevelLoadedText_DeathMatch2", "Tuez, tuez, tuez ! Tout le monde est ennemi !" },
                { "LevelLoadedText_DeathMatch3", "Il ne peut en rester qu\u2019un !" },
                { "LevelLoadedText_TeamMatch1", "Mort \u00E0 tous les ennemis !" },
                { "LevelLoadedText_TeamMatch2", "Que la meilleure \u00E9quipe gagne !" },
                { "LevelLoadedText_TeamMatch3", "C\u2019est la guerre !" },
                { "LevelDescription_PVP_BaseDefense_01", "Petite zone centr\u00E9e autour de l\u2019unit\u00E9 de traitement des d\u00E9chets.\\nJoueurs recommand\u00E9s : 4-6" },
                { "LevelDescription_PVP_BaseDefense_02", "Zone \u00E0 plusieurs niveaux avec de nombreuses passerelles.\\nJoueurs recommand\u00E9s : 2-4" },
                { "LevelDescription_PVP_Generic05", "Un seul entrep\u00F4t de technologies dangereuses, reli\u00E9 \u00E0 des couloirs de service.\\nJoueurs recommand\u00E9s : 6-8" },
                { "LevelDescription_PVP_Generic08", "Zone de stockage de maintenance avec une seule salle centrale.\\nJoueurs recommand\u00E9s : 2-4" },
                { "LevelDescription_PVP_Generic09", "Module de recherche \u00E9cologique avec arbres et v\u00E9g\u00E9tation.\\nJoueurs recommand\u00E9s : 2-4" },
                { "LevelDescription_PVP_Generic11", "N\u0153ud de fret avec couloirs d\u2019acc\u00E8s adjacents.\\nJoueurs recommand\u00E9s : 4-6" },
                { "LevelDescription_PVP_Generic13", "Petite zone inond\u00E9e.\\nJoueurs recommand\u00E9s : 2-4" },
                { "LevelDescription_PVP_Generic14", "Petite zone de service.\\nJoueurs recommand\u00E9s : 2-4" },
                { "LevelDescription_PVP_Generic15", "Grande salle centrale avec de nombreuses passerelles.\\nJoueurs recommand\u00E9s : 4-6" },
                { "LevelDescription_PVP_Generic16", "Zone \u00E0 plusieurs niveaux, avec \u00E9tage inf\u00E9rieur inond\u00E9.\\nJoueurs recommand\u00E9s : 2-4" },
                { "LevelDescription_PVP_Generic17", "Zone interconnect\u00E9e avec vue sur l\u2019ext\u00E9rieur.\\nJoueurs recommand\u00E9s : 2-4" },
                { "LevelDescription_PVP_Generic18", "Plusieurs salles entour\u00E9es de longs couloirs.\\nJoueurs recommand\u00E9s : 2-4" },
                { "LevelDescription_PVP_Generic20", "Grande salle centrale entour\u00E9e de passerelles et de positions de tir \u00E0 longue port\u00E9e.\\nJoueurs recommand\u00E9s : 4-6" },
                { "LevelDescription_PVP_Generic21", "Grande passerelle \u00E0 plusieurs niveaux avec ascenseurs et coursives.\\nJoueurs recommand\u00E9s : 6-8" },
            }},
