                { "Player_SwordSwitch1.D", "J'ai envie de faire \u00E7a \u00E0 l'ancienne." },
                { "Player_SwordSwitch1.F", "Quelqu'un a command\u00E9 une mort \u00E0 l'arme blanche ?" },
