                { "QuestTask_GetConnected_Gen01_killSoldiers", "\u00C9liminer les soldats des forces sp\u00E9ciales." },
                { "QuestTask_GetConnected_Gen01_leave", "Quitter la zone." },
                { "GetConnected/MissionStart1", "\u00C7a ne va pas \u00EAtre facile, mais tu vas y arriver. Pr\u00EAt pour la bagarre ?" },
                { "GetConnected/MissionStart2.D", "Je suis N\u00C9 pr\u00EAt. Allons-y." },
                { "GetConnected/MissionStart2.F", "Je suis N\u00C9E pr\u00EAte. Allons-y." },
                { "GetConnected/MissionStart2.R", "Toujours pr\u00EAt." },
                { "GetConnected/MissionStart2.X", "Toujours pr\u00EAte." },
                { "GetConnected/MissionStart3", "Toute la zone est prot\u00E9g\u00E9e par un champ de force." },
                { "GetConnected/MissionStart4", "D\u00E9sactive-le. Puis d\u00E9cha\u00EEne l\u2019enfer." },
                { "GetConnected/AlarmStart1", "Attention. Int\u00E9grit\u00E9 du champ de force compromise. Alerte." },
                { "GetConnected/AlarmStart2", "Danger critique. D\u00E9ploiement de toutes les unit\u00E9s disponibles requis. Alerte." },
                { "GetConnected/AlarmStart3", "Acc\u00E8s non autoris\u00E9 \u00E0 la zone prot\u00E9g\u00E9e d\u00E9tect\u00E9. Alerte rouge." },
                { "GetConnected/AlarmStart4", "Toutes les unit\u00E9s. S\u00E9curisez la zone compromise." },
                { "GetConnected/AlarmStart5", "Attention. L\u2019ennemi est arm\u00E9 et dangereux." },
