            if (!scriptMain.Contains("Je suis Kay. Je tue des gens. Avec mon \u00E9p\u00E9e.")) throw new InvalidDataException("V1.0.0 player selection Kay validation text missing.");
            if (!HasFrenchForKey(scriptMain, "Introducing1.X")) throw new InvalidDataException("V1.0.0 player selection Xandria key/French validation failed.");
            if (!scriptMain.Contains("&[respiration]")) throw new InvalidDataException("V1.0.0 player breathing subtitle validation text missing.");
