            if (!scriptMain.Contains("Minikin r\u00E9pare \u00E7a ! Toi regarder !")) throw new InvalidDataException("V1.0.0 Fixer Minikin validation text missing.");
            if (!scriptMain.Contains("Je suis le grand Chercheur de Sang. Je vais les trouver.")) throw new InvalidDataException("V1.0.0 BloodSamples player validation text missing.");
