            if (!scriptExpansion.Contains("Minikin reste, contr\u00F4le saut !")) throw new InvalidDataException("V1.0.0 U8 validation text missing.");
            if (!scriptExpansion.Contains("Ne la combats pas ! Rejoins-moi !")) throw new InvalidDataException("V1.0.0 U9 validation text missing.");
            if (!scriptExpansion.Contains("Bonne chance ! Pas oublier Minikin !")) throw new InvalidDataException("V1.0.0 U10 validation text missing.");
            if (!scriptExpansion.Contains("Un mois plus tard\u2026")) throw new InvalidDataException("V1.0.0 HUBE intro validation text missing.");
            if (!scriptExpansion.Contains("Danette mal\u00E9fique ?")) throw new InvalidDataException("V1.0.0 HUBE Danette validation text missing.");
            if (!scriptExpansion.Contains("Minikin conna\u00EEt pas autre plan.")) throw new InvalidDataException("V1.0.0 HUBE Minikin validation text missing.");
            if (!scriptExpansion.Contains("La simulation est assez r\u00E9aliste. Tu peux continuer \u00E0 t\u2019entra\u00EEner, rejouer tes anciennes missions\u2026")) throw new InvalidDataException("V1.0.0 HUBE epilogue validation text missing.");
            if (!scriptExpansion.Contains("mais c'est une autre histoire")) throw new InvalidDataException("V1.0.0 expansion outro validation text missing.");

            if (!gui.Contains("Nouvelle partie")) throw new InvalidDataException("V1.0.0 main menu validation text missing.");
            if (!gui.Contains("Prise/maintien des armes")) throw new InvalidDataException("V1.0.0 VR controls validation text missing.");
            if (!gui.Contains("Volume du chat vocal")) throw new InvalidDataException("V1.0.0 audio options validation text missing.");
