            if (!gui.Contains("Lissage des armes \u00E0 deux mains")) throw new InvalidDataException("V1.0.0 two-handed smoothing validation text missing.");
            if (!gui.Contains("STATS DU PERSONNAGE")) throw new InvalidDataException("V1.0.0 tablet validation text missing.");
            if (!gui.Contains("SERVICES DE MESSAGERIE MERIDIAN")) throw new InvalidDataException("V1.0.0 email tablet validation text missing.");
            if (!expansionGui.Contains("Sp\u00E9cialiste tech.")) throw new InvalidDataException("V1.0.0 expansion character selection validation text missing.");
            if (!expansionGui.Contains("Explosion du c\u0153ur")) throw new InvalidDataException("V1.0.0 expansion ability validation text missing.");

            string mission = ReadTextAssetScript(sf.ReadObject(6089));
            if (!mission.Contains("Sauv\u00E9 du cong\u00E9lateur")) throw new InvalidDataException("V1.0.0 mission regression validation text missing.");
            if (!mission.Contains("Tous \u00E0 bord du Meridian Express !")) throw new InvalidDataException("V1.0.0 main mission validation text missing.");
            if (!mission.Contains("Pour une poign\u00E9e de plutonium")) throw new InvalidDataException("V1.0.0 mission title validation text missing.");
            string expansionMission = ReadTextAssetScript(sf.ReadObject(6861));
