            if (!script.Contains("Les soldats nous traquent ?")) throw new InvalidDataException("V1.0.0 narrative regression validation text missing.");
            if (!script.Contains("Le premier vaisseau de colonisation interstellaire")) throw new InvalidDataException("V1.0.0 opening intro regression validation text missing.");
            string email = ReadTextAssetScript(sf.ReadObject(6690));
            if (!email.Contains("Rapport du projet PowerFish")) throw new InvalidDataException("V1.0.0 multiline email regression validation text missing.");
        }
    }
