function Write-ResultZip([string]$GamePath,[string]$Action,[string]$BeforeHash,[string]$AfterHash,[string]$Message) {
    $stamp = Get-Date -Format "yyyy-MM-dd_HH-mm-ss"
    $work = Join-Path $ReportDir ("Report_" + $stamp)
    New-Item -ItemType Directory -Force -Path $work | Out-Null
    $summary = @(
        "Dead Effect 2 VR - FR Production $Version",
        "Action: $Action",
        "Game: $GamePath",
        "Before SHA256: $BeforeHash",
        "After SHA256: $AfterHash",
        "Message: $Message"
    )
    [IO.File]::WriteAllLines((Join-Path $work "00_RESUME.txt"),$summary,[Text.UTF8Encoding]::new($true))
    if (Test-Path -LiteralPath $LogPath) { Copy-Item -LiteralPath $LogPath -Destination (Join-Path $work "PATCH.log") -Force }
    $zip = Join-Path $ReportDir ("Rapport_DeadEffect2VR_FR_TestPatch_" + $Version + "_" + $stamp + ".zip")
    if (Test-Path -LiteralPath $zip) { Remove-Item -LiteralPath $zip -Force }
    Add-Type -AssemblyName System.IO.Compression.FileSystem
    [IO.Compression.ZipFile]::CreateFromDirectory($work,$zip,[IO.Compression.CompressionLevel]::Optimal,$false)
    Remove-Item -LiteralPath $work -Recurse -Force
    Write-Host ""
    Write-Host ("Report: " + $zip) -ForegroundColor Cyan
}

try {
