        $before = if (Test-Path -LiteralPath $resources) { Get-Sha256 $resources } else { "MISSING" }
        $safetyCopy = Join-Path $backupDir ("resources.assets.before_restore_" + (Get-Date -Format "yyyyMMdd_HHmmss") + ".bak")
        if (Test-Path -LiteralPath $resources) { Copy-Item -LiteralPath $resources -Destination $safetyCopy -Force }
        Copy-Item -LiteralPath $backup -Destination $resources -Force
        $after = Get-Sha256 $resources
        if ($after -ne $ExpectedOriginalSha256) { throw "Restore verification failed." }
