        [IO.File]::Replace($temp,$resources,$null,$true)
    }
    catch {
        Copy-Item -LiteralPath $temp -Destination $resources -Force
        Remove-Item -LiteralPath $temp -Force -ErrorAction SilentlyContinue
    }
